.eyebrow.blood{color:#a8211a}
.eyebrow.dim{color:#a8a094}
.hero{font-size:44px;font-weight:700;line-height:1;letter-spacing:-.01em;text-transform:uppercase}
.hero.blood{color:#a8211a}
.value{font-size:26px;font-weight:600;line-height:1.1;text-transform:uppercase}
.value small{font-size:13px;font-weight:500;color:#a8a094;letter-spacing:.04em;margin-left:4px}
.sub{font-family:'JetBrains Mono',ui-monospace,'SF Mono',Menlo,Consolas,monospace;font-size:11px;color:#a8a094;letter-spacing:.04em;line-height:1.5}
.faint{color:#5a564f}
.mono{font-family:'JetBrains Mono',ui-monospace,'SF Mono',Menlo,Consolas,monospace}
.prose{font-family:'Merriweather',Georgia,'Times New Roman',serif;font-size:13px;line-height:1.55;color:#a8a094}
.rule{border-top:1px solid #2a2622}
.stack{display:flex;flex-direction:column;justify-content:flex-start;gap:10px;height:100%}
.stack.spread{justify-content:space-between;gap:0}
.row{display:flex;gap:0;height:100%}
.card{flex:1;min-width:0;padding:0 18px;border-left:1px solid #2a2622;display:flex;flex-direction:column;justify-content:space-between}
.card:first-child{padding-left:0;border-left:0}
.card .top{display:flex;flex-direction:column;gap:6px}
