.chip.miss{color:#5a564f;text-decoration:line-through}
.chip.blood{color:#a8211a;border-color:#a8211a_DIM}
.bar{height:2px;background:#2a2622;position:relative;margin-top:8px}
.bar i{position:absolute;left:0;top:0;bottom:0;background:#a8211a;display:block}
.bar.dim i{background:#a8a094}
.empty{color:#5a564f;font-family:'JetBrains Mono',ui-monospace,'SF Mono',Menlo,Consolas,monospace;font-size:11px;letter-spacing:.08em;text-transform:uppercase}
.list{display:flex;flex-direction:column}
.item{display:flex;align-items:baseline;gap:12px;padding:6px 0;border-top:1px solid #2a2622;font-family:'JetBrains Mono',ui-monospace,'SF Mono',Menlo,Consolas,monospace;font-size:12px}
.item:first-child{border-top:0}
.item .when{color:#5a564f;font-size:10px;letter-spacing:.08em;text-transform:uppercase;min-width:64px}
.item .txt{color:#ebe5d8;flex:1;min-width:0}
.item .num{color:#a8a094;white-space:nowrap}
.set{display:flex;align-items:baseline;gap:10px;font-family:'JetBrains Mono',ui-monospace,'SF Mono',Menlo,Consolas,monospace;font-size:12px;padding:3px 0}
.set .n{color:#5a564f;font-size:10px;min-width:16px}
.set .w{color:#ebe5d8;min-width:46px;text-align:right}
.set .x{color:#5a564f}
.set .r{color:#ebe5d8;min-width:28px}
.set .rpe{color:#a8a094}
.set .note{color:#5a564f;font-size:11px;flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.set.prep .w,.set.prep .r{color:#a8a094}
.ex{margin-bottom:10px}
.ex .name{font-size:15px;font-weight:600;text-transform:uppercase;letter-spacing:.02em;line-height:1.3}
.ex .name .cat{font-family:'JetBrains Mono',ui-monospace,'SF Mono',Menlo,Consolas,monospace;font-size:9px;letter-spacing:.16em;color:#5a564f;margin-left:8px;font-weight:500}
.cols{column-count:2;column-gap:36px}
.cols .ex{break-inside:avoid}
.grid3{display:grid;grid-template-columns:repeat(3,1fr);gap:4px 8px}
.k{color:#5a564f}
.v{color:#ebe5d8}
.hdr{display:flex;align-items:baseline;gap:14px;flex-wrap:wrap}
.hdr .title{font-size:26px;font-weight:700;text-transform:uppercase;letter-spacing:-.01em;line-height:1}
.hdr .meta{font-family:'JetBrains Mono',ui-monospace,'SF Mono',Menlo,Consolas,monospace;font-size:11px;color:#a8a094;letter-spacing:.06em;text-transform:uppercase}
.hdr .meta b{color:#ebe5d8;font-weight:500}
.dot{display:inline-block;width:7px;height:7px;background:#a8211a;margin:0 8px;vertical-align:middle}
svg{display:block}
</style>
